import React from "react"
import { INDICES } from "../../data/markets"

/**
 * The market summary bar that sits under the main navigation.
 *
 * Values and percentage moves come from src/data/markets.js; the absolute
 * change there is derived from the percentage, so the two can never disagree.
 * On narrow screens the row scrolls horizontally rather than wrapping.
 */

function formatValue(index) {
  if (index.format === "currency-compact") {
    return "$" + (index.value / 1000).toFixed(0) + "K"
  }
  if (index.format === "plain") {
    return index.value.toFixed(1)
  }
  return index.value.toLocaleString("en-US", {
    minimumFractionDigits: index.value < 100 ? 2 : 0,
    maximumFractionDigits: index.value < 100 ? 2 : 0,
  })
}

export default function MarketTicker() {
  return (
    <div className="ticker">
      <div className="ticker__inner">
        <ul className="ticker__list" aria-label="Market summary">
          {INDICES.map(index => (
            <li className="ticker__item" key={index.key}>
              <span className="ticker__name">{index.name}</span>
              <span className="ticker__row">
                <span className="ticker__value">{formatValue(index)}</span>
                <span className={"ticker__change ticker__change--" + index.direction}>
                  {index.changePct > 0 ? "+" : ""}
                  {index.changePct.toFixed(2)}%
                </span>
              </span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  )
}
