import React from "react"
import Header from "./Header"
import MarketTicker from "./MarketTicker"

/**
 * Page shell: navigation, the market summary bar, then the page content in a
 * centred container.
 *
 * `location` is supplied by Gatsby to every page component, so the header can
 * mark the active nav item without reading window.location during SSR.
 */
export default function Shell({ children, location, showTicker = true }) {
  const pathname = location && location.pathname ? location.pathname : ""

  return (
    <div className="shell">
      <Header pathname={pathname} />
      {showTicker && <MarketTicker />}
      <main className="shell__main">
        <div className="shell__container">{children}</div>
      </main>
    </div>
  )
}
