import React, { useEffect, useRef, useState } from "react"
import { Link } from "gatsby"
import Icon, { LogoMark } from "../ui/Icon"
import { getMarketStatus } from "../../data/markets"

/**
 * Top navigation.
 *
 * The Analysis item opens a dropdown; it closes on outside click, on Escape and
 * on route change. Both listeners are attached inside useEffect, so nothing
 * touches `document` during the server render Gatsby performs at build time.
 */

const NAV = [
  { label: "Dashboard", to: "/" },
  { label: "Markets", to: "/markets/" },
  { label: "Scanner", to: "/scanner/" },
  {
    label: "Analysis",
    children: [
      { label: "Technical", to: "/technical/", desc: "Price action and indicators" },
      { label: "Fundamentals", to: "/fundamentals/", desc: "Valuation, growth and margins" },
      { label: "Delta", to: "/delta/", desc: "What changed, and by how much" },
    ],
  },
  { label: "Breakouts", to: "/breakouts/" },
  { label: "Watchlist", to: "/watchlist/" },
  { label: "News", to: "/news/" },
]

const ANALYSIS_PATHS = ["/technical", "/fundamentals", "/delta"]

export default function Header({ pathname = "" }) {
  const [analysisOpen, setAnalysisOpen] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const analysisRef = useRef(null)
  const status = getMarketStatus()

  const analysisActive = ANALYSIS_PATHS.some(p => pathname.startsWith(p))

  useEffect(() => {
    if (!analysisOpen) return undefined

    function onPointerDown(event) {
      if (analysisRef.current && !analysisRef.current.contains(event.target)) {
        setAnalysisOpen(false)
      }
    }
    function onKeyDown(event) {
      if (event.key === "Escape") setAnalysisOpen(false)
    }

    document.addEventListener("mousedown", onPointerDown)
    document.addEventListener("keydown", onKeyDown)
    return () => {
      document.removeEventListener("mousedown", onPointerDown)
      document.removeEventListener("keydown", onKeyDown)
    }
  }, [analysisOpen])

  // Any navigation closes both menus.
  useEffect(() => {
    setAnalysisOpen(false)
    setMobileOpen(false)
  }, [pathname])

  const isActive = to => (to === "/" ? pathname === "/" : pathname.startsWith(to.replace(/\/$/, "")))

  return (
    <header className="header">
      <div className="header__inner">
        <Link className="header__brand" to="/">
          <span className="header__logo">
            <LogoMark size={20} />
          </span>
          <span className="header__wordmark">
            <span className="header__name">MarketScan</span>
            <span className="header__tagline">Find opportunity. Trade smarter.</span>
          </span>
        </Link>

        <nav className="header__nav" aria-label="Primary">
          {NAV.map(item => {
            if (item.children) {
              return (
                <div className="header__nav-item" key={item.label} ref={analysisRef}>
                  <button
                    type="button"
                    className={
                      "header__nav-link" +
                      (analysisActive ? " header__nav-link--active" : "")
                    }
                    aria-expanded={analysisOpen}
                    aria-haspopup="true"
                    onClick={() => setAnalysisOpen(open => !open)}
                  >
                    {item.label}
                    <Icon
                      name="chevronDown"
                      size={14}
                      className={
                        "header__nav-caret" +
                        (analysisOpen ? " header__nav-caret--open" : "")
                      }
                    />
                  </button>
                  {analysisOpen && (
                    <div className="header__dropdown">
                      {item.children.map(child => (
                        <Link className="header__dropdown-link" to={child.to} key={child.to}>
                          <span className="header__dropdown-title">{child.label}</span>
                          <span className="header__dropdown-desc">{child.desc}</span>
                        </Link>
                      ))}
                    </div>
                  )}
                </div>
              )
            }
            return (
              <div className="header__nav-item" key={item.to}>
                <Link
                  className={
                    "header__nav-link" + (isActive(item.to) ? " header__nav-link--active" : "")
                  }
                  to={item.to}
                >
                  {item.label}
                </Link>
              </div>
            )
          })}
        </nav>

        <div className="header__tools">
          <span className="header__status">
            <span
              className={
                "header__status-dot" + (status.isOpen ? "" : " header__status-dot--closed")
              }
            />
            {status.label}
          </span>

          <div className="header__search">
            <Icon name="search" size={16} className="header__search-icon" />
            <input
              className="header__search-input"
              type="search"
              placeholder="Search stocks, ETFs…"
              aria-label="Search stocks and ETFs"
            />
            <span className="header__search-kbd">⌘K</span>
          </div>

          <button
            type="button"
            className="header__icon-button"
            aria-label="Search"
          >
            <Icon name="search" size={18} />
          </button>

          <button
            type="button"
            className="header__icon-button"
            aria-label={mobileOpen ? "Close menu" : "Open menu"}
            aria-expanded={mobileOpen}
            onClick={() => setMobileOpen(open => !open)}
          >
            <Icon name={mobileOpen ? "close" : "menu"} size={18} />
          </button>

          <button type="button" className="header__avatar" aria-label="Account menu">
            AR
          </button>
        </div>
      </div>

      <div className={"header__mobile-nav" + (mobileOpen ? " header__mobile-nav--open" : "")}>
        {NAV.filter(i => !i.children).map(item => (
          <Link
            className={
              "header__mobile-link" + (isActive(item.to) ? " header__mobile-link--active" : "")
            }
            to={item.to}
            key={item.to}
          >
            {item.label}
          </Link>
        ))}
        <div className="header__mobile-group">
          <p className="header__mobile-label">Analysis</p>
          {NAV.find(i => i.children).children.map(child => (
            <Link
              className={
                "header__mobile-link" + (isActive(child.to) ? " header__mobile-link--active" : "")
              }
              to={child.to}
              key={child.to}
            >
              {child.label}
            </Link>
          ))}
        </div>
      </div>
    </header>
  )
}
