/**
 * Market-level data: the index ticker, the dashboard performance chart, and the
 * headline sentiment and breadth figures.
 *
 * Same discipline as the rest of the data layer — seeded, frozen to
 * ANCHOR_DATE, identical on every reload. The sentiment and breadth numbers are
 * DERIVED from the same signals and candles the rest of the app renders, so the
 * KPI cards cannot disagree with the tables underneath them.
 */

import { rngFor, gaussian } from "./rng.js"
import { ANCHOR_DATE, SYMBOLS, getCompany } from "./companies.js"
import { generateCandles } from "./candles.js"
import { getSignalSummary } from "./signals.js"

const ANCHOR_UTC_OFFSET_HOURS = -4
const DAY_MS = 86400000
const [A_Y, A_M, A_D] = ANCHOR_DATE.split("-").map(Number)

/** Ranges offered by the dashboard chart's time control. */
export const CHART_RANGES = ["1D", "1W", "1M", "3M", "6M", "1Y"]

const RANGE_BARS = { "1D": 390, "1W": 5, "1M": 21, "3M": 63, "6M": 126, "1Y": 252 }

/*
 * Index levels as of the anchor close. Percentage moves are the session change;
 * the absolute change is derived from them so the two can never disagree.
 */
const RAW_INDICES = [
  { key: "SPX", name: "S&P 500", value: 5842.18, changePct: 0.42, format: "index", volatility: 0.008 },
  { key: "NDX", name: "NASDAQ", value: 18421.4, changePct: 0.71, format: "index", volatility: 0.011 },
  { key: "DJI", name: "DOW", value: 43210, changePct: 0.18, format: "index", volatility: 0.007 },
  { key: "BTC", name: "BTC", value: 112480, changePct: 1.2, format: "currency-compact", volatility: 0.028 },
  { key: "VIX", name: "VIX", value: 16.4, changePct: -2.1, format: "plain", volatility: 0.045 },
]

export const INDICES = RAW_INDICES.map(i => {
  const previousClose = i.value / (1 + i.changePct / 100)
  return {
    ...i,
    previousClose: Math.round(previousClose * 100) / 100,
    changeAbs: Math.round((i.value - previousClose) * 100) / 100,
    direction: i.changePct > 0 ? "up" : i.changePct < 0 ? "down" : "flat",
  }
})

const INDEX_BY_KEY = INDICES.reduce((acc, i) => {
  acc[i.key] = i
  return acc
}, {})

export function getIndex(key) {
  return INDEX_BY_KEY[key] || INDICES[0]
}

/* --------------------------------------------------------------------------
   Index series for the dashboard chart.
   Same Brownian-bridge technique as candles.js: both endpoints pinned, so the
   last point is exactly the level quoted above the chart.
   -------------------------------------------------------------------------- */

function sessionOpenSeconds() {
  const utcMinutes = 9 * 60 + 30 - ANCHOR_UTC_OFFSET_HOURS * 60
  return Math.floor(Date.UTC(A_Y, A_M - 1, A_D, 0, utcMinutes, 0) / 1000)
}

function tradingDayStamps(count) {
  const closeUtcHour = 16 - ANCHOR_UTC_OFFSET_HOURS
  let cursor = Date.UTC(A_Y, A_M - 1, A_D, closeUtcHour, 0, 0)
  const stamps = []
  while (stamps.length < count) {
    const weekday = new Date(cursor).getUTCDay()
    if (weekday !== 0 && weekday !== 6) stamps.push(Math.floor(cursor / 1000))
    cursor -= DAY_MS
  }
  return stamps.reverse()
}

/**
 * A deterministic index series ending exactly on the quoted level.
 * Returns [{ time, value }] — a line series, which is what the dashboard draws.
 */
export function generateIndexSeries(key, range) {
  const index = getIndex(key)
  const bars = RANGE_BARS[range] || RANGE_BARS["1M"]
  const intraday = range === "1D"
  const rand = rngFor("INDEX", index.key, range)

  const times = intraday
    ? Array.from({ length: bars }, (_, i) => sessionOpenSeconds() + i * 60)
    : tradingDayStamps(bars)

  const end = index.value
  // Over one session the move is the quoted change; over longer ranges the
  // index drifts, more for the volatile instruments.
  const start = intraday
    ? index.previousClose
    : end / Math.exp(gaussian(rand) * index.volatility * Math.sqrt(bars) * 0.35 + 0.05 * (bars / 252))

  const stepSigma = intraday
    ? index.volatility / Math.sqrt(bars)
    : index.volatility

  const walk = new Array(bars)
  walk[0] = 0
  for (let i = 1; i < bars; i += 1) walk[i] = walk[i - 1] + gaussian(rand) * stepSigma
  const drift = walk[bars - 1]

  const logStart = Math.log(start)
  const logEnd = Math.log(end)

  const points = new Array(bars)
  for (let i = 0; i < bars; i += 1) {
    const t = bars === 1 ? 1 : i / (bars - 1)
    const bridged = walk[i] - t * drift
    const value = Math.exp(logStart + t * (logEnd - logStart) + bridged)
    points[i] = { time: times[i], value: Math.round(value * 100) / 100 }
  }
  points[bars - 1] = { time: times[bars - 1], value: Math.round(end * 100) / 100 }
  return points
}

/* --------------------------------------------------------------------------
   Market status.
   The anchor is a Wednesday session, so the tape is open. Derived from the
   frozen clock rather than the real one, which keeps it stable in a demo.
   -------------------------------------------------------------------------- */

export function getMarketStatus() {
  return {
    isOpen: true,
    label: "Market open",
    detail: "US markets · closes 4:00 PM ET",
  }
}

/* --------------------------------------------------------------------------
   Sentiment and breadth, derived from the same data the tables render.
   -------------------------------------------------------------------------- */

/** Session change for a symbol, read off its 1D series. */
export function getSessionChange(symbol) {
  const candles = generateCandles(symbol, "1D")
  if (!candles.length) return { price: null, changePct: null, changeAbs: null, direction: "flat" }
  const open = candles[0].open
  const close = candles[candles.length - 1].close
  const changeAbs = close - open
  const changePct = open > 0 ? (changeAbs / open) * 100 : 0
  return {
    price: close,
    changeAbs: Math.round(changeAbs * 100) / 100,
    changePct: Math.round(changePct * 100) / 100,
    direction: changePct > 0 ? "up" : changePct < 0 ? "down" : "flat",
  }
}

/**
 * Sentiment: the share of all technical signals across every tracked ticker
 * that read bullish. Same getSignalSummary the signal badges use.
 */
export function getMarketSentiment() {
  let bullish = 0
  let total = 0
  for (const symbol of SYMBOLS) {
    const s = getSignalSummary(symbol, "1D")
    bullish += s.bullish
    total += s.total
  }
  const pct = total > 0 ? Math.round((bullish / total) * 100) : 0
  const label = pct >= 60 ? "Bullish" : pct <= 40 ? "Bearish" : "Neutral"
  return { pct, label, bullish, total }
}

/** Breadth: the share of tracked tickers advancing on the session. */
export function getMarketBreadth() {
  let advancing = 0
  for (const symbol of SYMBOLS) {
    if (getSessionChange(symbol).changePct > 0) advancing += 1
  }
  const total = SYMBOLS.length
  return {
    advancing,
    declining: total - advancing,
    total,
    pct: total > 0 ? Math.round((advancing / total) * 100) : 0,
  }
}

/* --------------------------------------------------------------------------
   Watchlist. The tracked set for the dashboard and the watchlist screen.
   -------------------------------------------------------------------------- */

export const WATCHLIST = SYMBOLS.slice()

export function getWatchlist() {
  return WATCHLIST.map(symbol => {
    const company = getCompany(symbol)
    const change = getSessionChange(symbol)
    const summary = getSignalSummary(symbol, "1D")
    return {
      symbol,
      name: company.name,
      brandColor: company.brandColor,
      price: change.price,
      changePct: change.changePct,
      changeAbs: change.changeAbs,
      direction: change.direction,
      bias: summary.bias,
      bullish: summary.bullish,
      total: summary.total,
    }
  })
}

/**
 * Top opportunities: the tracked names ranked by how many technical signals
 * read bullish, then by session change. Signal wording maps the bullish count
 * onto a familiar research-desk rating.
 */
export function getTopOpportunities(limit = 6) {
  const rows = getWatchlist().map(row => {
    let signal = "Neutral"
    if (row.bullish >= 5) signal = "Strong buy"
    else if (row.bullish === 4) signal = "Buy"
    else if (row.bullish <= 1) signal = "Sell"
    else if (row.bullish === 2) signal = "Reduce"
    return { ...row, signal }
  })
  return rows
    .sort((a, b) => b.bullish - a.bullish || b.changePct - a.changePct || a.symbol.localeCompare(b.symbol))
    .slice(0, limit)
}

/**
 * Trend series for sparklines.
 *
 * THE RULE THIS EXISTS TO ENFORCE: a sparkline and the percentage change shown
 * next to it must describe the SAME WINDOW. The previous version sampled a
 * one-month series while the table printed the session change, so 8 of 14 rows
 * rendered a rising green line beside a red percentage — precisely the thing
 * that makes a trader stop trusting a screen.
 *
 * So the window is an explicit argument, `changePct` is computed from the very
 * same array the line is drawn from, and `direction` derives from that change
 * rather than from a first-vs-last comparison of a differently-scoped series.
 * Callers render the tone from `direction` and label the window from `label`.
 */
const TREND_WINDOWS = {
  "1D": { timeframe: "1D", label: "1D" },
  "5D": { timeframe: "5D", label: "5D" },
  "1M": { timeframe: "1M", label: "1M" },
  "3M": { timeframe: "3M", label: "3M" },
  "1Y": { timeframe: "1Y", label: "1Y" },
}

export function getTrend(symbol, window = "1D", points = 56) {
  const config = TREND_WINDOWS[window] || TREND_WINDOWS["1D"]
  const candles = generateCandles(symbol, config.timeframe)
  if (!candles.length) {
    return { values: [], changePct: null, changeAbs: null, direction: "flat", window: config.label, label: config.label }
  }

  // Evenly sample so every sparkline in a table has the same horizontal
  // resolution regardless of how many bars its timeframe holds.
  const values = []
  const n = candles.length
  const target = Math.min(points, n)
  for (let i = 0; i < target; i += 1) {
    const idx = target === 1 ? n - 1 : Math.round((i * (n - 1)) / (target - 1))
    values.push(candles[idx].close)
  }

  // The reference is the window's opening price, so the line, the change and
  // the colour all describe one thing.
  const open = candles[0].open
  const close = candles[n - 1].close
  const changeAbs = close - open
  const changePct = open > 0 ? (changeAbs / open) * 100 : null

  return {
    values,
    baseline: open,
    changeAbs: Math.round(changeAbs * 100) / 100,
    changePct: changePct === null ? null : Math.round(changePct * 100) / 100,
    direction: changePct === null || changePct === 0 ? "flat" : changePct > 0 ? "up" : "down",
    window: config.label,
    label: config.label,
  }
}

/**
 * Signal score and confidence.
 *
 * The six technical checks in signals.js are the evidence; this turns them into
 * one rating plus a stated confidence, so the badge is never a bare colour.
 * Confidence reflects AGREEMENT — six signals pointing the same way is a
 * stronger read than a three-three split, regardless of which way it leans.
 */
export function getSignalScore(symbol, timeframe = "1D") {
  const s = getSignalSummary(symbol, timeframe)
  const total = s.total || 6
  const decided = s.bullish + s.bearish

  // 0-100, centred on 50 when bullish and bearish cancel out.
  const score = Math.round(((s.bullish - s.bearish) / total) * 50 + 50)

  let label = "Neutral"
  if (score >= 75) label = "Strong buy"
  else if (score >= 60) label = "Buy"
  else if (score <= 25) label = "Sell"
  else if (score <= 40) label = "Reduce"

  // Agreement among the signals that actually took a side.
  const agreement = decided === 0 ? 0 : Math.abs(s.bullish - s.bearish) / decided
  const coverage = decided / total
  const confidenceValue = Math.round(agreement * coverage * 100)
  const confidence = confidenceValue >= 66 ? "High" : confidenceValue >= 33 ? "Medium" : "Low"

  return {
    score,
    label,
    confidence,
    confidenceValue,
    bullish: s.bullish,
    bearish: s.bearish,
    neutral: s.neutral,
    total,
    reason: `${s.bullish} of ${total} technical checks bullish, ${s.bearish} bearish`,
  }
}


/**
 * Deprecated: use getTrend(symbol, window) instead, which ties the line, the
 * percentage and the colour to one window. Retained only so no import breaks
 * during the refactor.
 */
export function getSparkline(symbol, points = 24) {
  return getTrend(symbol, "1D", points).values
}
