import React from "react"

/**
 * Inline icon set, drawn in the Lucide style: 24x24 viewBox, 2px strokes,
 * round caps and joins, currentColor throughout.
 *
 * Inlined rather than pulled from a package so there is no runtime dependency,
 * no icon-font flash, and no raw colour value outside tokens.css.
 */

const PATHS = {
  search: <><circle cx="11" cy="11" r="7" /><path d="m20 20-3.2-3.2" /></>,
  chevronDown: <path d="m6 9 6 6 6-6" />,
  plus: <path d="M12 5v14M5 12h14" />,
  menu: <path d="M4 6h16M4 12h16M4 18h16" />,
  close: <path d="M6 6l12 12M18 6L6 18" />,
  trendingUp: <><path d="M22 7 13.5 15.5 8.5 10.5 2 17" /><path d="M16 7h6v6" /></>,
  activity: <path d="M22 12h-4l-3 9L9 3l-3 9H2" />,
  barChart: <path d="M12 20V10M18 20V4M6 20v-4" />,
  eye: <><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7Z" /><circle cx="12" cy="12" r="3" /></>,
  zap: <path d="M13 2 4 14h7l-1 8 9-12h-7l1-8Z" />,
  gauge: <><path d="M12 14 15.5 9.5" /><path d="M3.5 18a9 9 0 1 1 17 0" /></>,
  arrowUpRight: <><path d="M7 17 17 7" /><path d="M8 7h9v9" /></>,
  newspaper: <><path d="M4 4h13v16H4z" /><path d="M17 8h3v9a3 3 0 0 1-3 3" /><path d="M8 8h5M8 12h5M8 16h5" /></>,
  filter: <path d="M3 5h18l-7 8v6l-4-2v-4L3 5Z" />,
  star: <path d="m12 3 2.6 5.6 6 .8-4.4 4.2 1.1 6L12 16.8 6.7 19.6l1.1-6L3.4 9.4l6-.8L12 3Z" />,
  sortDesc: <><path d="M4 6h10M4 12h7M4 18h4" /><path d="M17 8v10m0 0 3-3m-3 3-3-3" /></>,
}

export default function Icon({ name, size = 16, className, strokeWidth = 2, ...rest }) {
  const glyph = PATHS[name]
  if (!glyph) return null

  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      {glyph}
    </svg>
  )
}

/**
 * The MarketScan mark: an "M" whose two peaks ascend, so it reads both as the
 * letter and as a pair of rising price lines.
 */
export function LogoMark({ size = 20, className }) {
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.4"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      <path d="M5 19V7l7 7 7-9v14" />
    </svg>
  )
}
