/**
 * Technical indicators, computed from the same candle arrays the chart draws.
 *
 * THE ALIGNMENT RULE, which everything else in the app depends on:
 * every function here returns an array the SAME LENGTH as its input, padded with
 * `null` at the front wherever the indicator is not yet defined. Index i of the
 * output always corresponds to index i of the input.
 *
 * That is what lets a sidebar read `ema9[ema9.length - 1]` and be certain it is
 * quoting the exact value the blue line is plotted at. Returning a short array
 * (the naive approach) silently shifts every value by `period` bars and makes
 * the sidebar disagree with the chart.
 */

import { generateCandles } from "./candles.js"

function nullArray(n) {
  return new Array(n).fill(null)
}

/** Simple moving average, null-padded. */
export function sma(values, period) {
  const n = values.length
  const out = nullArray(n)
  if (period <= 0 || n < period) return out

  let sum = 0
  for (let i = 0; i < n; i += 1) {
    sum += values[i]
    if (i >= period) sum -= values[i - period]
    if (i >= period - 1) out[i] = sum / period
  }
  return out
}

/**
 * Exponential moving average, seeded with the SMA of the first `period` values.
 * First defined value lands at index period - 1.
 */
export function ema(values, period) {
  const n = values.length
  const out = nullArray(n)
  if (period <= 0 || n < period) return out

  const k = 2 / (period + 1)

  let seed = 0
  for (let i = 0; i < period; i += 1) seed += values[i]
  out[period - 1] = seed / period

  for (let i = period; i < n; i += 1) {
    out[i] = (values[i] - out[i - 1]) * k + out[i - 1]
  }
  return out
}

/**
 * Relative Strength Index using Wilder's smoothing.
 *
 * The seed average consumes the first `period` price CHANGES, which span
 * indices 1..period — so the first RSI value lands at index `period`, not
 * period - 1. Off-by-one here is the classic RSI bug.
 */
export function rsi(closes, period = 14) {
  const n = closes.length
  const out = nullArray(n)
  if (period <= 0 || n < period + 1) return out

  let gainSum = 0
  let lossSum = 0
  for (let i = 1; i <= period; i += 1) {
    const change = closes[i] - closes[i - 1]
    if (change >= 0) gainSum += change
    else lossSum -= change
  }

  let avgGain = gainSum / period
  let avgLoss = lossSum / period
  out[period] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss)

  for (let i = period + 1; i < n; i += 1) {
    const change = closes[i] - closes[i - 1]
    const gain = change > 0 ? change : 0
    const loss = change < 0 ? -change : 0
    avgGain = (avgGain * (period - 1) + gain) / period
    avgLoss = (avgLoss * (period - 1) + loss) / period
    out[i] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss)
  }
  return out
}

/**
 * MACD line, signal line and histogram — all three full-length and null-padded.
 *
 * The subtle part is the signal line. Running ema() straight over the null-padded
 * MACD array would treat those leading nulls as numbers and poison the seed. So
 * we extract the contiguous defined span, run the EMA over just that, then write
 * the results back at their correct absolute offsets.
 */
export function macd(closes, fast = 12, slow = 26, signal = 9) {
  const n = closes.length
  const fastEma = ema(closes, fast)
  const slowEma = ema(closes, slow)

  const macdLine = nullArray(n)
  let start = -1
  for (let i = 0; i < n; i += 1) {
    if (fastEma[i] !== null && slowEma[i] !== null) {
      macdLine[i] = fastEma[i] - slowEma[i]
      if (start === -1) start = i
    }
  }

  const signalLine = nullArray(n)
  const histogram = nullArray(n)

  if (start !== -1) {
    const span = macdLine.slice(start)
    const spanSignal = ema(span, signal)
    for (let j = 0; j < spanSignal.length; j += 1) {
      if (spanSignal[j] !== null) signalLine[start + j] = spanSignal[j]
    }
  }

  for (let i = 0; i < n; i += 1) {
    if (macdLine[i] !== null && signalLine[i] !== null) {
      histogram[i] = macdLine[i] - signalLine[i]
    }
  }

  return { macd: macdLine, signal: signalLine, histogram }
}

/**
 * Volume-weighted average price, cumulative from the first bar of the series.
 * Non-null from index 0 onward, so it always has a value to quote.
 */
export function vwap(candles) {
  const n = candles.length
  const out = nullArray(n)
  let cumulativePV = 0
  let cumulativeVolume = 0

  for (let i = 0; i < n; i += 1) {
    const c = candles[i]
    const typical = (c.high + c.low + c.close) / 3
    cumulativePV += typical * c.volume
    cumulativeVolume += c.volume
    out[i] = cumulativeVolume > 0 ? cumulativePV / cumulativeVolume : typical
  }
  return out
}

/**
 * Average True Range, Wilder-smoothed.
 * TR[0] is simply high - low, since there is no previous close to gap from.
 */
export function atr(candles, period = 14) {
  const n = candles.length
  const out = nullArray(n)
  if (period <= 0 || n < period) return out

  const tr = new Array(n)
  tr[0] = candles[0].high - candles[0].low
  for (let i = 1; i < n; i += 1) {
    const prevClose = candles[i - 1].close
    tr[i] = Math.max(
      candles[i].high - candles[i].low,
      Math.abs(candles[i].high - prevClose),
      Math.abs(candles[i].low - prevClose)
    )
  }

  let seed = 0
  for (let i = 0; i < period; i += 1) seed += tr[i]
  out[period - 1] = seed / period

  for (let i = period; i < n; i += 1) {
    out[i] = (out[i - 1] * (period - 1) + tr[i]) / period
  }
  return out
}

function lastOf(array) {
  if (!Array.isArray(array) || array.length === 0) return null
  const value = array[array.length - 1]
  return value === undefined ? null : value
}

const EMPTY = {
  candles: [],
  closes: [],
  ema9: [],
  ema20: [],
  ema50: [],
  ema200: [],
  rsi14: [],
  macd: { macd: [], signal: [], histogram: [] },
  vwap: [],
  atr14: [],
  latest: {
    close: null, ema9: null, ema20: null, ema50: null, ema200: null,
    rsi14: null, macd: null, macdSignal: null, macdHistogram: null,
    vwap: null, atr14: null, high: null, low: null, volume: null, time: null,
  },
}

/**
 * The single entry point the UI should use.
 *
 * Builds the candles ONCE and derives everything from that one array, then
 * assembles `latest` purely by indexing length-1 of each series. Nothing in
 * `latest` is recalculated — it is a sample of the arrays the chart plots.
 */
export function getIndicators(symbol, timeframe) {
  const candles = generateCandles(symbol, timeframe)
  if (!candles.length) return { symbol, timeframe, ...EMPTY }

  const closes = candles.map(c => c.close)
  const ema9 = ema(closes, 9)
  const ema20 = ema(closes, 20)
  const ema50 = ema(closes, 50)
  const ema200 = ema(closes, 200)
  const rsi14 = rsi(closes, 14)
  const macdSet = macd(closes, 12, 26, 9)
  const vwapLine = vwap(candles)
  const atr14 = atr(candles, 14)

  const lastCandle = candles[candles.length - 1]

  return {
    symbol,
    timeframe,
    candles,
    closes,
    ema9,
    ema20,
    ema50,
    ema200,
    rsi14,
    macd: macdSet,
    vwap: vwapLine,
    atr14,
    latest: {
      close: lastCandle.close,
      high: lastCandle.high,
      low: lastCandle.low,
      volume: lastCandle.volume,
      time: lastCandle.time,
      ema9: lastOf(ema9),
      ema20: lastOf(ema20),
      ema50: lastOf(ema50),
      ema200: lastOf(ema200),
      rsi14: lastOf(rsi14),
      macd: lastOf(macdSet.macd),
      macdSignal: lastOf(macdSet.signal),
      macdHistogram: lastOf(macdSet.histogram),
      vwap: lastOf(vwapLine),
      atr14: lastOf(atr14),
    },
  }
}
