/**
 * Technical signals and price levels, derived at call time.
 *
 * Nothing in this file is a lookup table. Every verdict is computed from
 * getIndicators(symbol, timeframe), which reads the same candle array the chart
 * draws — so if a badge says Bullish because EMA 9 is above EMA 20, the blue
 * line really is above the orange one on screen.
 *
 * The short-series case matters: a 5-bar "5D" series has no EMA 20, EMA 50,
 * RSI or MACD. Those signals return "Neutral" with "Not enough data" rather
 * than NaN, null or a crash.
 */

import { getIndicators } from "./indicators.js"

const BULLISH = "Bullish"
const BEARISH = "Bearish"
const NEUTRAL = "Neutral"
const NO_DATA = "Not enough data"

/** Price formatting that stays readable for a $4 stock and a $505 one alike. */
function fmt(value) {
  if (value === null || !Number.isFinite(value)) return "—"
  const abs = Math.abs(value)
  const digits = abs < 1 ? 4 : abs < 20 ? 3 : 2
  return value.toFixed(digits)
}

function defined(...values) {
  return values.every(v => v !== null && Number.isFinite(v))
}

function compare(a, b, labelA, labelB) {
  if (!defined(a, b)) return { verdict: NEUTRAL, value: NO_DATA }
  const verdict = a > b ? BULLISH : a < b ? BEARISH : NEUTRAL
  return { verdict, value: `${labelA} ${fmt(a)} vs ${labelB} ${fmt(b)}` }
}

/**
 * The psychological price ladder used for R2 and S1 — the round numbers traders
 * actually watch, which scale with the price.
 *
 * The step has to stay proportionate. A flat $1 step would round a $4.08 stock's
 * $3.82 low down to $3.00: a 21% gap that lands below its own 52-week low and
 * makes the support marker useless. Half the tickers here trade under $20, so
 * the bottom of the ladder is where the resolution matters most.
 */
function ladderStep(price) {
  if (!Number.isFinite(price)) return 1
  const abs = Math.abs(price)
  if (abs < 5) return 0.25
  if (abs < 20) return 0.5
  if (abs < 100) return 5
  if (abs < 500) return 10
  return 50
}

function roundUpTo(price) {
  if (!Number.isFinite(price)) return null
  const step = ladderStep(price)
  const up = Math.ceil(price / step) * step
  // If the price is already exactly on a level, the next one up is the level above.
  return Math.round((up === price ? up + step : up) * 100) / 100
}

function roundDownTo(price) {
  if (!Number.isFinite(price)) return null
  const step = ladderStep(price)
  return Math.round(Math.floor(price / step) * step * 100) / 100
}

/**
 * Six signals, in a fixed order, each { key, label, value, verdict }.
 */
export function getSignals(symbol, timeframe) {
  const data = getIndicators(symbol, timeframe)
  const { candles, latest } = data

  if (!candles.length) {
    return {
      symbol,
      timeframe,
      signals: [],
      levels: { r1: null, r2: null, s1: null, s2: null },
    }
  }

  const n = candles.length
  const prev = n >= 2 ? candles[n - 2] : null

  // 1. Price vs VWAP
  const priceVsVwap = compare(latest.close, latest.vwap, "Close", "VWAP")

  // 2. EMA 9 vs EMA 20
  const ema9VsEma20 = compare(latest.ema9, latest.ema20, "EMA 9", "EMA 20")

  // 3. EMA 20 vs EMA 50
  const ema20VsEma50 = compare(latest.ema20, latest.ema50, "EMA 20", "EMA 50")

  // 4. RSI zone: overbought is a bearish tell, oversold a bullish one.
  let rsiZone
  if (!defined(latest.rsi14)) {
    rsiZone = { verdict: NEUTRAL, value: NO_DATA }
  } else if (latest.rsi14 > 70) {
    rsiZone = { verdict: BEARISH, value: `${latest.rsi14.toFixed(1)} — overbought` }
  } else if (latest.rsi14 < 30) {
    rsiZone = { verdict: BULLISH, value: `${latest.rsi14.toFixed(1)} — oversold` }
  } else {
    rsiZone = { verdict: NEUTRAL, value: `${latest.rsi14.toFixed(1)} — neutral` }
  }

  // 5. MACD histogram sign
  let macdHistogram
  if (!defined(latest.macdHistogram)) {
    macdHistogram = { verdict: NEUTRAL, value: NO_DATA }
  } else {
    const h = latest.macdHistogram
    macdHistogram = {
      verdict: h > 0 ? BULLISH : h < 0 ? BEARISH : NEUTRAL,
      value: `${h > 0 ? "+" : ""}${h.toFixed(4)}`,
    }
  }

  // 6. Close vs the previous bar's high / low
  let closeVsPrevHigh
  if (!prev) {
    closeVsPrevHigh = { verdict: NEUTRAL, value: NO_DATA }
  } else if (latest.close > prev.high) {
    closeVsPrevHigh = {
      verdict: BULLISH,
      value: `${fmt(latest.close)} above prior high ${fmt(prev.high)}`,
    }
  } else if (latest.close < prev.low) {
    closeVsPrevHigh = {
      verdict: BEARISH,
      value: `${fmt(latest.close)} below prior low ${fmt(prev.low)}`,
    }
  } else {
    closeVsPrevHigh = {
      verdict: NEUTRAL,
      value: `${fmt(latest.close)} inside prior range`,
    }
  }

  const signals = [
    { key: "priceVsVwap", label: "Price vs VWAP", ...priceVsVwap },
    { key: "ema9VsEma20", label: "EMA 9 vs EMA 20", ...ema9VsEma20 },
    { key: "ema20VsEma50", label: "EMA 20 vs EMA 50", ...ema20VsEma50 },
    { key: "rsiZone", label: "RSI (14)", ...rsiZone },
    { key: "macdHistogram", label: "MACD histogram", ...macdHistogram },
    { key: "closeVsPrevHigh", label: "Close vs prior high", ...closeVsPrevHigh },
  ]

  // Levels. R1/S1 come straight off the series; R2 and S1 snap to the ladder.
  let seriesHigh = -Infinity
  let seriesLow = Infinity
  for (const c of candles) {
    if (c.high > seriesHigh) seriesHigh = c.high
    if (c.low < seriesLow) seriesLow = c.low
  }

  const levels = {
    r1: Math.round(seriesHigh * 100) / 100,
    r2: roundUpTo(seriesHigh),
    s1: roundDownTo(seriesLow),
    s2: defined(latest.ema50) ? Math.round(latest.ema50 * 100) / 100 : null,
  }

  return { symbol, timeframe, signals, levels }
}

/**
 * Majority bias across the six signals. Ties resolve to Neutral.
 * breakouts.js uses this for its technical sub-score.
 */
export function getSignalSummary(symbol, timeframe) {
  const { signals } = getSignals(symbol, timeframe)
  let bullish = 0
  let bearish = 0
  let neutral = 0

  for (const s of signals) {
    if (s.verdict === BULLISH) bullish += 1
    else if (s.verdict === BEARISH) bearish += 1
    else neutral += 1
  }

  const bias = bullish > bearish ? BULLISH : bearish > bullish ? BEARISH : NEUTRAL
  return { bullish, bearish, neutral, total: signals.length, bias }
}
