/**
 * Deterministic pseudo-random number generation.
 *
 * Nothing in the data layer may call Math.random(). Every series in MarketScan
 * is generated from a seed derived from its own identity — usually the ticker
 * symbol plus a timeframe — so the same inputs always produce byte-identical
 * output, on every reload and on every machine. That is what stops the numbers
 * shifting halfway through a demo.
 *
 * The standard entry point is rngFor(...parts), which hashes its arguments into
 * a seed and returns an independent stream. Two consumers that pass different
 * parts never interfere with each other.
 */

/**
 * FNV-1a, 32-bit. Math.imul keeps the multiply in 32-bit integer space so the
 * result is identical in every JS engine — a plain `*` would silently lose
 * precision past 2^53 and drift between Node and a browser bundle.
 */
export function hashString(str) {
  let hash = 0x811c9dc5
  const s = String(str)
  for (let i = 0; i < s.length; i += 1) {
    hash ^= s.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193)
  }
  return hash >>> 0
}

/**
 * Mulberry32: a small, fast, well-distributed 32-bit PRNG.
 * Returns a function yielding floats in [0, 1).
 */
export function mulberry32(seed) {
  let a = seed >>> 0
  return function next() {
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/**
 * The seeder every consumer should use.
 * rngFor("AAPL", "1D") and rngFor("AAPL", "5D") are independent streams.
 */
export function rngFor(...parts) {
  return mulberry32(hashString(parts.join("|")))
}

export function randRange(rand, min, max) {
  return min + rand() * (max - min)
}

/** Inclusive of both bounds; clamped so a rand() of ~1 cannot overshoot. */
export function randInt(rand, min, max) {
  const lo = Math.ceil(min)
  const hi = Math.floor(max)
  if (hi <= lo) return lo
  const value = lo + Math.floor(rand() * (hi - lo + 1))
  return value > hi ? hi : value
}

export function pick(rand, array) {
  if (!Array.isArray(array) || array.length === 0) return undefined
  return array[randInt(rand, 0, array.length - 1)]
}

/**
 * Box-Muller standard normal.
 *
 * Deliberately does NOT cache the second variate. A cached variate makes the
 * stream depend on how many times the caller happened to draw before, so
 * changing an unrelated line upstream would silently reshuffle every chart.
 * Burning the second value costs nothing and keeps each call self-contained.
 */
export function gaussian(rand) {
  let u1 = rand()
  if (u1 <= Number.EPSILON) u1 = Number.EPSILON
  const u2 = rand()
  return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2)
}
