/**
 * The 14 companies in the MarketScan prototype.
 *
 * Determinism: this module is pure literal data plus arithmetic. There is no
 * RNG here and no clock — the numbers are the numbers.
 *
 * Structure: RAW holds only *authored* facts (price, share count, the five-year
 * income statement, balance-sheet lines). Every ratio — market cap, P/E, net
 * margin, ROE, ROA, growth and CAGR — is DERIVED from those facts below, so a
 * fundamentals screen can never show a P/E that contradicts the EPS printed
 * next to it.
 *
 * All money is in raw US dollars. The UI humanises it for display.
 */

export const ANCHOR_DATE = "2026-09-09"

/** The last complete fiscal year in the dataset; its EPS is the ttm figure behind P/E. */
export const LATEST_FISCAL_YEAR = 2025

const B = 1e9
const M = 1e6

/* --------------------------------------------------------------------------
   Derivation helpers.
   Every one returns a finite number or null — never NaN, never Infinity.
   -------------------------------------------------------------------------- */

function safeDiv(numerator, denominator) {
  if (!Number.isFinite(numerator) || !Number.isFinite(denominator)) return null
  if (denominator === 0) return null
  const value = numerator / denominator
  return Number.isFinite(value) ? value : null
}

/**
 * A margin on negligible revenue is arithmetically valid but meaningless — a
 * pre-revenue company can post a -4,000% net margin. Past +/-1000% we return
 * null so the UI shows an em dash instead of noise.
 */
function margin(numerator, revenue) {
  const value = safeDiv(numerator, revenue)
  if (value === null) return null
  return Math.abs(value) > 10 ? null : value
}

/** Year-over-year growth. Null when the base is zero or negative (growth off a loss is not a number). */
function growth(prev, curr) {
  if (!Number.isFinite(prev) || !Number.isFinite(curr)) return null
  if (prev <= 0) return null
  return (curr - prev) / prev
}

/** Compound annual growth rate. Null unless both ends are positive — no fractional powers of negatives. */
function cagr(start, end, years) {
  if (!Number.isFinite(start) || !Number.isFinite(end)) return null
  if (start <= 0 || end <= 0 || years <= 0) return null
  const value = Math.pow(end / start, 1 / years) - 1
  return Number.isFinite(value) ? value : null
}

/** P/E is undefined for a loss-making company. Return null rather than a negative multiple. */
function priceEarnings(price, eps) {
  if (!Number.isFinite(price) || !Number.isFinite(eps) || eps <= 0) return null
  const value = price / eps
  return Number.isFinite(value) ? value : null
}

